<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Core/WorkflowHelpers.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::sendSecurityHeaders($config);Security::startSession($config);
if(!Security::enforceAuthenticatedSession($config)){Security::destroySession();header('Location: login.php');exit;}
try{$db=Database::connection();$user=Authorization::user($db,(int)$_SESSION['user_id']);if(!$user){Security::destroySession();header('Location: login.php');exit;}if($user['role_code']!=='BARANGAY_ADMINISTRATOR'||!Authorization::can($db,$user,'roles.manage')||!Authorization::can($db,$user,'officials.manage')){http_response_code(403);exit('Administrator role and RBAC management permissions required.');}}
catch(Throwable $e){error_log('RBAC manager: '.$e->getMessage());http_response_code(503);exit('RBAC management is unavailable.');}
$message=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);$error='Session expired. Refresh and try again.';}
 else try{$action=(string)($_POST['action']??'');$db->beginTransaction();
  if($action==='grant_permission'||$action==='revoke_permission'){$position=(int)($_POST['position_id']??0);$permission=(int)($_POST['permission_id']??0);if($position<1||$permission<1)throw new InvalidArgumentException('Choose a valid position and permission.');$exists=$db->prepare('SELECT 1 FROM official_positions WHERE position_id=:id AND is_active=1');$exists->execute(['id'=>$position]);if(!$exists->fetchColumn())throw new InvalidArgumentException('The selected position is inactive or missing.');$exists=$db->prepare('SELECT 1 FROM permissions WHERE permission_id=:id');$exists->execute(['id'=>$permission]);if(!$exists->fetchColumn())throw new InvalidArgumentException('The selected permission is missing.');if($action==='grant_permission'){$q=$db->prepare('INSERT IGNORE INTO position_permissions (position_id,permission_id,granted_by_user_id) VALUES (:p,:perm,:uid)');$q->execute(['p'=>$position,'perm'=>$permission,'uid'=>$user['user_id']]);$event='POSITION_PERMISSION_GRANTED';}else{$q=$db->prepare('DELETE FROM position_permissions WHERE position_id=:p AND permission_id=:perm');$q->execute(['p'=>$position,'perm'=>$permission]);$event='POSITION_PERMISSION_REVOKED';}AuditLogger::record($db,(int)$user['user_id'],$event,'official_position',$position,['permission_id'=>$permission]);$message='Position permission updated.';
  }elseif($action==='create_assignment'){
   $officialUser=(int)($_POST['user_id']??0);$position=(int)($_POST['position_id']??0);$start=trim((string)($_POST['term_start']??''));$end=trim((string)($_POST['term_end']??''));
   if($officialUser<1||$position<1||!WorkflowHelpers::validDate($start)||($end!==''&&!WorkflowHelpers::validDate($end))||($end!==''&&$end<$start))throw new InvalidArgumentException('Choose an Official account, position, and valid term dates.');
   $q=$db->prepare("SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.user_id JOIN roles r ON r.role_id=ur.role_id WHERE u.user_id=:uid AND u.account_type='OFFICIAL' AND u.account_status='ACTIVE' AND u.email_verified_at IS NOT NULL AND r.role_code='BARANGAY_OFFICIAL' LIMIT 1");$q->execute(['uid'=>$officialUser]);if(!$q->fetchColumn())throw new InvalidArgumentException('The selected user must be an active, email-verified Official account with the BARANGAY_OFFICIAL role.');
   $q=$db->prepare('SELECT 1 FROM official_positions WHERE position_id=:pid AND is_active=1');$q->execute(['pid'=>$position]);if(!$q->fetchColumn())throw new InvalidArgumentException('Select an active official position.');
   $q=$db->prepare("INSERT INTO official_assignments (user_id,position_id,term_start,term_end,verification_status,assignment_status,notes) VALUES (:uid,:pid,:start,:end,'PENDING','SCHEDULED','Created in RBAC management; requires verification and activation.')");$q->execute(['uid'=>$officialUser,'pid'=>$position,'start'=>$start,'end'=>$end?:null]);$id=(int)$db->lastInsertId();AuditLogger::record($db,(int)$user['user_id'],'OFFICIAL_ASSIGNMENT_CREATED','official_assignment',$id,['user_id'=>$officialUser,'position_id'=>$position]);$message='Official assignment created as PENDING / SCHEDULED. Verify and activate it after checking official records.';
  }elseif($action==='update_assignment'){$id=(int)($_POST['assignment_id']??0);$verify=(string)($_POST['verification_status']??'');$state=(string)($_POST['assignment_status']??'');$start=trim((string)($_POST['term_start']??''));$end=trim((string)($_POST['term_end']??''));$validVerify=['PENDING','VERIFIED','REJECTED'];$validState=['SCHEDULED','ACTIVE','ENDED','REVOKED'];if($id<1||!in_array($verify,$validVerify,true)||!in_array($state,$validState,true)||!WorkflowHelpers::validDate($start)||($end!==''&&!WorkflowHelpers::validDate($end))||($end!==''&&$end<$start))throw new InvalidArgumentException('Check the assignment ID, status, and term dates.');$q=$db->prepare('SELECT user_id FROM official_assignments WHERE official_assignment_id=:id FOR UPDATE');$q->execute(['id'=>$id]);$officialUser=(int)$q->fetchColumn();if(!$officialUser)throw new InvalidArgumentException('Official assignment not found.');$q=$db->prepare("SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.user_id JOIN roles r ON r.role_id=ur.role_id WHERE u.user_id=:uid AND u.account_type='OFFICIAL' AND r.role_code='BARANGAY_OFFICIAL' LIMIT 1");$q->execute(['uid'=>$officialUser]);if(!$q->fetchColumn())throw new InvalidArgumentException('The assigned account is not a provisioned Barangay Official.');if($state==='ACTIVE'&&$verify==='VERIFIED'){$q=$db->prepare("SELECT COUNT(*) FROM official_assignments WHERE user_id=:uid AND official_assignment_id<>:id AND assignment_status='ACTIVE' AND verification_status='VERIFIED' AND term_start<=CURRENT_DATE() AND (term_end IS NULL OR term_end>=CURRENT_DATE())");$q->execute(['uid'=>$officialUser,'id'=>$id]);if((int)$q->fetchColumn()>0)throw new InvalidArgumentException('This account already has another active verified assignment. Resolve that assignment first.');}$q=$db->prepare('UPDATE official_assignments SET term_start=:start,term_end=:end,verification_status=:verify,assignment_status=:state,verified_by_user_id=CASE WHEN :verify2=\'VERIFIED\' THEN :uid ELSE NULL END,verified_at=CASE WHEN :verify3=\'VERIFIED\' THEN NOW() ELSE NULL END WHERE official_assignment_id=:id');$q->execute(['start'=>$start,'end'=>$end?:null,'verify'=>$verify,'state'=>$state,'verify2'=>$verify,'uid'=>$user['user_id'],'verify3'=>$verify,'id'=>$id]);AuditLogger::record($db,(int)$user['user_id'],'OFFICIAL_ASSIGNMENT_UPDATED','official_assignment',$id,['verification_status'=>$verify,'assignment_status'=>$state]);$message='Official assignment updated.';
  }else throw new InvalidArgumentException('Unknown RBAC action.');
  $db->commit();
 }catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('RBAC action: '.$e->getMessage());$error='Unable to update RBAC configuration.';}
}
$positions=$db->query('SELECT position_id,position_code,position_name FROM official_positions ORDER BY position_name')->fetchAll(PDO::FETCH_ASSOC);$permissions=$db->query('SELECT permission_id,permission_code,permission_name,module_name FROM permissions ORDER BY permission_id')->fetchAll(PDO::FETCH_ASSOC);$assignments=$db->query("SELECT oa.official_assignment_id,oa.user_id,u.username,op.position_name,oa.term_start,oa.term_end,oa.verification_status,oa.assignment_status FROM official_assignments oa JOIN users u ON u.user_id=oa.user_id JOIN official_positions op ON op.position_id=oa.position_id ORDER BY oa.created_at DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);$grants=$db->query('SELECT pp.position_id,pp.permission_id,op.position_name,p.permission_code FROM position_permissions pp JOIN official_positions op ON op.position_id=pp.position_id JOIN permissions p ON p.permission_id=pp.permission_id ORDER BY op.position_name,p.permission_id')->fetchAll(PDO::FETCH_ASSOC);
require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('Role & Position Permissions','Manage official position-based authorization.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">ADMINISTRATIVE CONTROL</p><h1>Role &amp; Position Permissions</h1><p>Official permissions are granted by verified position assignments only. Generic BARANGAY_OFFICIAL role permissions are never used.</p></div></section><section class="section"><?php if($message): ?><div class="notice info" role="status"><?= Security::e($message) ?></div><?php endif; ?><?php if($error): ?><div class="notice warning" role="alert"><?= Security::e($error) ?></div><?php endif; ?>
<div class="content-layout"><article class="content-panel"><h2>Grant or revoke a position permission</h2><form class="portal-form" method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><label>Official position *<select name="position_id" required><option value="">Choose position</option><?php foreach($positions as $p): ?><option value="<?= (int)$p['position_id'] ?>"><?= Security::e($p['position_name']) ?></option><?php endforeach; ?></select></label><label>Permission *<select name="permission_id" required><option value="">Choose permission</option><?php foreach($permissions as $p): ?><option value="<?= (int)$p['permission_id'] ?>"><?= Security::e($p['permission_code'].' — '.$p['permission_name']) ?></option><?php endforeach; ?></select></label><div class="workflow-actions"><button class="action-primary" name="action" value="grant_permission" type="submit">Grant permission</button><button class="action-secondary" name="action" value="revoke_permission" type="submit">Revoke permission</button></div></form></article><article class="content-panel"><h2>Create an official assignment</h2><p class="micro">The user must already have an active Official account. New assignments start as PENDING / SCHEDULED.</p><form class="portal-form" method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><label>Official user ID *<input type="number" name="user_id" min="1" required></label><label>Position *<select name="position_id" required><option value="">Choose position</option><?php foreach($positions as $p): ?><option value="<?= (int)$p['position_id'] ?>"><?= Security::e($p['position_name']) ?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Term start *<input type="date" name="term_start" required></label><label>Term end<input type="date" name="term_end"></label></div><button class="auth-submit" name="action" value="create_assignment" type="submit">Create pending assignment</button></form></article><article class="content-panel"><h2>Update an official assignment</h2><p class="micro">This changes the assignment record for an already provisioned Official account. It does not create a user account.</p><form class="portal-form" method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><label>Assignment ID *<input type="number" name="assignment_id" min="1" required></label><label>Verification status *<select name="verification_status"><option>PENDING</option><option>VERIFIED</option><option>REJECTED</option></select></label><label>Assignment status *<select name="assignment_status"><option>SCHEDULED</option><option>ACTIVE</option><option>ENDED</option><option>REVOKED</option></select></label><div class="form-grid"><label>Term start *<input type="date" name="term_start" required></label><label>Term end<input type="date" name="term_end"></label></div><button class="auth-submit" name="action" value="update_assignment" type="submit">Save assignment</button></form></article></div>
<section class="workflow-section"><h2>Current position permission map</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Position</th><th>Permission</th></tr></thead><tbody><?php foreach($grants as $g): ?><tr><td><?= Security::e($g['position_name']) ?></td><td><?= Security::e($g['permission_code']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="workflow-section"><h2>Official assignments</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Username</th><th>Position</th><th>Term</th><th>Verification</th><th>Assignment</th></tr></thead><tbody><?php foreach($assignments as $a): ?><tr><td><?= (int)$a['official_assignment_id'] ?></td><td><?= Security::e($a['username']) ?></td><td><?= Security::e($a['position_name']) ?></td><td><?= Security::e($a['term_start'].' — '.($a['term_end']??'Open')) ?></td><td><?= Security::e($a['verification_status']) ?></td><td><?= Security::e($a['assignment_status']) ?></td></tr><?php endforeach; ?></tbody></table></div></section></section></main><?php pageFooter();
